 void home(){LinearLayout hero=new LinearLayout(this);hero.setGravity(Gravity.CENTER_VERTICAL);hero.setBackground(glass(0xfff1f1f1,28));grid.addView(hero,new LinearLayout.LayoutParams(-1,dp(180)));hero.addView(new OrbitClock(),new LinearLayout.LayoutParams(0,-1,1.1f));LinearLayout info=column();info.setGravity(Gravity.CENTER);hero.addView(info,new LinearLayout.LayoutParams(0,-1,1));info.addView(text("ORBIT",12,0xff3984f5));Date now=new Date();info.addView(text(new java.text.SimpleDateFormat("EEEE، d MMMM yyyy",new Locale("ar","TN")).format(now),14,0xff252525));android.icu.text.SimpleDateFormat fmt=new android.icu.text.SimpleDateFormat("d MMMM yyyy",new android.icu.util.ULocale("ar@calendar=islamic-civil"));info.addView(text(fmt.format(new Date(now.getTime()+prefs.getInt("hijriOffset",0)*86400000L))+" هـ",12,0xff414141));BatteryManager bm=(BatteryManager)getSystemService(BATTERY_SERVICE);int level=Math.max(0,Math.min(100,bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)));info.addView(text("البطارية  "+level+"%",13,0xff252525));ProgressBar battery=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);battery.setMax(100);battery.setProgress(level);battery.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff3984f5));info.addView(battery,new LinearLayout.LayoutParams(dp(86),dp(12)));heading("تطبيقاتي المفضلة");ArrayList<App> fav=new ArrayList<>();for(App app:apps)if(prefs.getBoolean("fav:"+app.key,false))fav.add(app);if(fav.isEmpty()){for(App app:apps)if(app.key.contains("whatsapp")||app.key.contains("telegram")||app.key.contains("instagram")||app.key.contains("zhiliao"))fav.add(app);for(App app:apps)if(fav.size()<6&&!fav.contains(app))fav.add(app);}for(int i=0;i<fav.size();i+=2){LinearLayout row=new LinearLayout(this);grid.addView(row);for(int j=i;j<Math.min(i+2,fav.size());j++)appCard(row,fav.get(j),true);if(i+1==fav.size())row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}heading("اختصارات الهاتف");LinearLayout shortcuts=new LinearLayout(this);grid.addView(shortcuts);String[] names={"الهاتف","الرسائل","الكاميرا","المتصفح"};for(int i=0;i<4;i++){final int k=i;LinearLayout cell=column();cell.setGravity(17);cell.setBackground(glass(0xff414141,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(72),1);lp.setMargins(dp(3),0,dp(3),0);shortcuts.addView(cell,lp);cell.addView(new DockIcon(i),new LinearLayout.LayoutParams(dp(30),dp(30)));cell.addView(text(names[i],11,Color.WHITE));cell.setOnClickListener(v->shortcut(k));}}
 void appCard(LinearLayout row,App app,boolean compact){LinearLayout card=new LinearLayout(this);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(8),dp(8),dp(8),dp(8));boolean pale=row.getChildCount()==0;card.setBackground(glass(pale?0xfff1f1f1:0xff414141,24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(compact?84:78),1);lp.setMargins(dp(3),dp(4),dp(3),dp(4));row.addView(card,lp);ImageView icon=new ImageView(this);icon.setImageDrawable(app.icon);card.addView(icon,new LinearLayout.LayoutParams(dp(58),dp(58)));TextView name=text(app.name,12,pale?0xff252525:Color.WHITE);name.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);name.setPadding(dp(4),0,0,0);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(name,new LinearLayout.LayoutParams(0,-1,1));card.setOnClickListener(v->launch(app));card.setOnLongClickListener(v->{String key="fav:"+app.key;boolean old=prefs.getBoolean(key,false);prefs.edit().putBoolean(key,!old).apply();Toast.makeText(this,old?"أزيل من المفضلة":"أضيف إلى المفضلة",0).show();if(screen==0)render();return true;});}
 void control(){LinearLayout panel=column();panel.setPadding(dp(20),dp(12),dp(20),dp(16));panel.setBackground(glass(0xff101827,24));TextView title=text("CONTROL X",22,0xfff0f0f0);panel.addView(title);TextView volume=text("مستوى الصوت",14,Color.WHITE);panel.addView(volume);android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);SeekBar bar=new SeekBar(this);bar.setMax(audio.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC));bar.setProgress(audio.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));panel.addView(bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){if(user)audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,p,0);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});panel.addView(text("سطوع الواجهة",14,Color.WHITE));SeekBar light=new SeekBar(this);light.setMax(100);light.setProgress(70);panel.addView(light);light.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){if(user){WindowManager.LayoutParams w=getWindow().getAttributes();w.screenBrightness=Math.max(.05f,p/100f);getWindow().setAttributes(w);}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});String[] labels={"إعدادات Wi-Fi","إعدادات Bluetooth","إعدادات الشاشة"};String[] actions={android.provider.Settings.ACTION_WIFI_SETTINGS,android.provider.Settings.ACTION_BLUETOOTH_SETTINGS,android.provider.Settings.ACTION_DISPLAY_SETTINGS};for(int j=0;j<labels.length;j++){final String action=actions[j];TextView t=text(labels[j],15,Color.WHITE);t.setBackground(glass(0xff24334e,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.setMargins(0,dp(6),0,0);panel.addView(t,lp);t.setOnClickListener(v->{try{startActivity(new Intent(action));}catch(Exception e){}});}grid.addView(panel,new LinearLayout.LayoutParams(-1,-2));}
 void shortcut(int k){try{Intent i=k==0?new Intent(Intent.ACTION_DIAL):k==1?new Intent(Intent.ACTION_SENDTO,android.net.Uri.parse("smsto:")):k==2?new Intent(android.provider.MediaStore.INTENT_ACTION_STILL_IMAGE_CAMERA):new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.google.com"));startActivity(i);}catch(Exception e){Toast.makeText(this,"التطبيق غير متوفر",0).show();}}
 void settings(){new AlertDialog.Builder(this).setTitle("BECHIR ULTRA").setItems(new String[]{"تعيين الواجهة الرئيسية","المظهر الرمادي","المظهر الداكن","اختيار التطبيقات المفضلة","استعادة المظهر الأصلي","تصحيح التاريخ الهجري"},(d,n)->{if(n==0){try{startActivity(new Intent(android.provider.Settings.ACTION_HOME_SETTINGS));}catch(Exception e){}}else if(n==3)page(true);else if(n==5){new AlertDialog.Builder(this).setTitle("تصحيح التاريخ الهجري").setSingleChoiceItems(new String[]{"-2","-1","0","+1","+2"},prefs.getInt("hijriOffset",0)+2,(dialog,i)->{prefs.edit().putInt("hijriOffset",i-2).apply();dialog.dismiss();recreate();}).show();}else{prefs.edit().putBoolean("black",n==2).apply();root.setBackground(new Aurora());root.invalidate();}}).show();}
 void launch(App a){try{startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName(a.info.activityInfo.packageName,a.info.activityInfo.name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){Toast.makeText(this,"تعذر فتح التطبيق",0).show();}}
 void tile(LinearLayout row,App a,int weight,int height,int iconSize,int tint){LinearLayout t=column();t.setGravity(Gravity.TOP|Gravity.CENTER_HORIZONTAL);t.setPadding(0,dp(6),0,0);t.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x33ffffff),null,null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(height),weight);p.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(t,p);ImageView icon=new ImageView(this);icon.setImageDrawable(a.icon);t.addView(icon,new LinearLayout.LayoutParams(dp(iconSize),dp(iconSize)));TextView name=text(a.name,12,Color.WHITE);name.setMaxLines(2);name.setMinLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(dp(3),dp(4),dp(3),0);t.addView(name,new LinearLayout.LayoutParams(-1,-2));t.setOnClickListener(v->{v.animate().scaleX(.94f).scaleY(.94f).setDuration(75).withEndAction(()->{v.setScaleX(1);v.setScaleY(1);launch(a);}).start();});t.setOnLongClickListener(v->{String key="fav:"+a.key;boolean old=prefs.getBoolean(key,false);prefs.edit().putBoolean(key,!old).putBoolean("custom",true).apply();Toast.makeText(this,old?"أزيل من المفضلة":"أضيف إلى المفضلة",0).show();render();return true;});}
 void render(){grid.removeAllViews();if(screen==0){home();return;}String q=search.getText().toString().toLowerCase(Locale.ROOT);String last="";LinearLayout row=null;for(App app:apps){if(!app.name.toLowerCase(Locale.ROOT).contains(q))continue;String letter=app.name.isEmpty()?"#":app.name.substring(0,1).toUpperCase(Locale.ROOT);if(!letter.equals(last)){if(row!=null&&row.getChildCount()==1)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));heading(letter);last=letter;row=null;}if(row==null||row.getChildCount()==2){row=new LinearLayout(this);grid.addView(row);}appCard(row,app,false);}if(row!=null&&row.getChildCount()==1)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
 void page(boolean value){showScreen(value?1:0);}
 protected void onResume(){super.onResume();if(grid!=null){load();if(screen!=2)render();}}
 @Override public void onBackPressed(){if(screen!=0)showScreen(0);}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);showScreen(0);}
 class Aurora extends Drawable{public void draw(Canvas c){c.drawColor(prefs.getBoolean("black",false)?0xff242424:0xff737373);}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.OPAQUE;}}
class OrbitClock extends View {Paint p=new Paint(3);OrbitClock(){super(MainActivity.this);}void hand(Canvas c,float angle,float length,float width,int color){p.setColor(color);p.setStrokeWidth(width);p.setStrokeCap(Paint.Cap.ROUND);double a=Math.toRadians(angle);c.drawLine(0,0,(float)Math.sin(a)*length,-(float)Math.cos(a)*length,p);}protected void onDraw(Canvas c){super.onDraw(c);float r=Math.min(getWidth(),getHeight())*.46f;c.save();c.translate(getWidth()/2f,getHeight()/2f);c.scale(r/100,r/100);p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(0,0,100,new int[]{0xff303030,0xff161616},null,Shader.TileMode.CLAMP));c.drawCircle(0,0,100,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);p.setShader(new SweepGradient(0,0,new int[]{0xfff1f1f1,0xffaaaaaa,0xffeeeeee,0xff999999,0xfff1f1f1},null));c.drawCircle(0,0,97,p);p.setShader(null);p.setStrokeWidth(2);p.setColor(0xff3984f5);c.drawCircle(0,0,91,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<60;i++){double a=i*Math.PI/30;float x=(float)Math.sin(a),y=-(float)Math.cos(a);p.setColor(i%5==0?0xfff1f1f1:0xffb0b0b0);p.setStrokeWidth(i%5==0?2:1);c.drawLine(x*(i%5==0?85:89),y*(i%5==0?85:89),x*92,y*92,p);}p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(14);p.setColor(Color.WHITE);for(int i=1;i<=12;i++){double a=i*Math.PI/6;c.drawText(""+i,(float)Math.sin(a)*73,-(float)Math.cos(a)*73+5,p);}p.setTextSize(8);p.setColor(0xffb6c9eb);c.drawText("ORBIT X",0,-29,p);Calendar now=Calendar.getInstance();float m=now.get(Calendar.MINUTE),sec=now.get(Calendar.SECOND);hand(c,(now.get(Calendar.HOUR)+m/60)*30,48,5,Color.WHITE);hand(c,(m+sec/60)*6,65,3,0xffdbeaff);hand(c,sec*6,79,1.4f,0xff3984f5);p.setColor(0xff3984f5);c.drawCircle(0,0,4,p);c.restore();if(isShown())postInvalidateDelayed(1000);} }
class DockIcon extends View {int k;Paint p=new Paint(3);DockIcon(int n){super(MainActivity.this);k=n;}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/48f,getHeight()/48f);p.setColor(0xffe4efff);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);if(k==0){Path a=new Path();a.moveTo(13,7);a.lineTo(21,16);a.lineTo(16,22);a.quadTo(20,30,27,33);a.lineTo(33,27);a.lineTo(41,35);a.quadTo(39,44,30,41);a.quadTo(10,34,7,15);a.close();c.drawPath(a,p);}else if(k==1){c.drawRoundRect(6,9,42,34,8,8,p);c.drawLine(14,34,10,41,p);c.drawLine(10,41,23,34,p);for(int i=0;i<3;i++)c.drawCircle(15+i*9,22,1,p);}else if(k==2){c.drawRoundRect(5,13,43,39,6,6,p);c.drawLine(16,13,20,7,p);c.drawLine(20,7,29,7,p);c.drawLine(29,7,33,13,p);c.drawCircle(24,26,8,p);}else{c.drawCircle(24,24,18,p);c.drawOval(15,6,33,42,p);c.drawLine(6,24,42,24,p);}c.restore();}}
